function hitMarker(sx, sy) {
  for (let i = markers.length - 1; i >= 0; i--) {
    const m = markers[i];
    if (Math.hypot(m.sx - sx, m.sy - sy) <= m.r) return m;
  }
  return null;
}
function biomeAt(x, z) {
  const bpp = levelBpp(), span = TILE * bpp;
  const t = findTile(bpp, Math.floor(x / span), Math.floor(z / span));
  if (!t) return null;
  const tspan = TILE * t.bpp, cb = tspan / t.cells;
  const i = Math.floor((x - t.tx * tspan) / cb), j = Math.floor((z - t.tz * tspan) / cb);
  if (i < 0 || j < 0 || i >= t.cells || j >= t.cells) return null;
  return t.ids[j * t.cells + i];
}
const pretty = (s) => s.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
function hover(sx, sy) {
  const [x, z] = toWorld(sx, sy);
  $('coords').textContent = `${Math.floor(x)}, ${Math.floor(z)}`;
  const id = biomeAt(x, z);
  $('biome').textContent = world && id != null && world.names[id] ? pretty(world.names[id]) : '';
  const m = hitMarker(sx, sy);
  const tip = $('tooltip');
  if (m) {
    tip.innerHTML = `${esc(m.name)}<small>${m.x}, ${m.z} · click to copy /tp</small>`;
    tip.style.left = sx + 'px';
    tip.style.top = sy + 'px';
    tip.hidden = false;
  } else tip.hidden = true;
}
async function click(sx, sy) {
  const m = hitMarker(sx, sy);
  if (!m) return;
  const cmd = `/tp @s ${m.x} ~ ${m.z}`;
  try {
    await navigator.clipboard.writeText(cmd);
    $('tooltip').innerHTML = `Copied <code>${cmd}</code>`;
  } catch {
    $('tooltip').innerHTML = `<code>${cmd}</code><small>Clipboard blocked; copy it by hand</small>`;
  }
}

// ---------- controls ----------
$('seed').addEventListener('change', (e) => { setSeedText(e.target.value); regenerate(); });
$('random').onclick = () => { setSeedText(randomSeed()); regenerate(); };
$('version').onchange = (e) => { settings.mc = +e.target.value; finder.stop(); regenerate(); };
function setDim(next) {
  const prev = settings.dim;
  if (next === prev) return;
  // Keep the same place in the world when hopping to/from the Nether.
  if (prev === 0 && next === -1) { view.x /= 8; view.z /= 8; }
  if (prev === -1 && next === 0) { view.x *= 8; view.z *= 8; }
  settings.dim = next;
  if (next !== 0 && settings.mode === '3d') setMode('relief');
  syncSegs();
  buildLayers();
  renderWaypoints();
  regenerate();
}
const DIM_ICON = { 0: 'overworld', '-1': 'nether', 1: 'end' }, MODE_ICON = { map: 'map', relief: 'relief', '3d': 'cube' };
for (const b of document.querySelectorAll('#dims button')) b.insertAdjacentHTML('afterbegin', svg(DIM_ICON[b.dataset.dim], 14));
for (const b of document.querySelectorAll('#modes button')) b.insertAdjacentHTML('afterbegin', svg(MODE_ICON[b.dataset.mode], 14));
for (const b of document.querySelectorAll('#dims button')) b.onclick = () => setDim(+b.dataset.dim);
for (const b of document.querySelectorAll('#modes button')) b.onclick = () => setMode(b.dataset.mode);
badgeEvents.addEventListener('load', () => draw());
function syncSegs() {
  const check = (b, v) => { b.classList.toggle('on', v); b.setAttribute('aria-checked', v); };
  for (const b of document.querySelectorAll('#dims button')) check(b, +b.dataset.dim === settings.dim);
  for (const b of document.querySelectorAll('#modes button')) {
    check(b, b.dataset.mode === settings.mode);
    b.disabled = b.dataset.mode === '3d' && (settings.dim !== 0 || settings.mc < 22);
    b.title = b.disabled ? 'Overworld only' : '';
  }
  document.body.classList.toggle('mode-3d', settings.mode === '3d');
}

// ---------- 3D ----------
let view3d = null, terrainReq = 0, lastMesh = null;
function setMode(mode) {
  const was = settings.mode;
  settings.mode = mode;
  syncSegs();
  saveHash();
  if (mode === '3d') return enter3D();
  if (was === '3d') {
    view3d?.stop();
    for (const id of ['view3d', 'hint3d', 'toolbar3d', 'readout']) $(id).hidden = true;
  }
  request();
  draw();
}
// three.js loads from a CDN, so load it only when 3D is opened: a blocked CDN
// then breaks 3D alone, not the whole site.
let view3dLoading = null;
async function load3D() {
  if (view3d) return view3d;
  view3dLoading ??= import('./view3d.js');
  const { createView3D } = await view3dLoading;
  view3d ??= createView3D($('view3d'), {
    tooltip: $('tooltip'),
    readout: showReadout,
    onPick: (c) => addWaypoint(c.x, c.z),
  });
  view3d.setCoords($('coords-toggle').classList.contains('on'));
  return view3d;
}
const N3D = 200;
const hint3d = () => `Drag to orbit · scroll to zoom · double-click to pin · arrow keys move · ${N3D * settings.size} × ${N3D * settings.size} blocks`;
function showReadout(c) {
  const el = $('readout');
  if (!c) { el.hidden = true; return; }
  const name = world?.names[c.biome];
  el.innerHTML = `<span><b>X</b>${c.x}</span><span><b>Y</b>${c.y}</span><span><b>Z</b>${c.z}</span>` +
    (name ? `<span class="bio">${pretty(name)}</span>` : '');
  el.hidden = false;
}
function pinsFor(m) {
  const size = m.n * m.s, inside = (p) => p.x >= m.x0 && p.z >= m.z0 && p.x < m.x0 + size && p.z < m.z0 + size;
  return allMarkers([{ found: m.found }]).filter(inside)
    .map((p) => ({ ...p, color: p.kind.color, badge: badge(p.kind.icon, p.kind.color) }));
}
async function enter3D({ keepCamera = false } = {}) {
  for (const id of ['view3d', 'hint3d', 'toolbar3d']) $(id).hidden = false;
  $('hint3d').textContent = 'Building terrain…';
  $('tooltip').hidden = true;
  const req = ++terrainReq;
  try { await load3D(); }
  catch (e) {
    view3dLoading = null;
    if (req === terrainReq) $('hint3d').textContent = /WebGL/i.test(e.message)
      ? '3D needs WebGL, which this browser has turned off.' : 'Couldn’t load the 3D engine. Check your connection.';
    return;
  }
  if (req !== terrainReq || settings.mode !== '3d') return;
  const structs = STRUCTS.filter((s) => s.dim === 0 && on.has(`s${s.id}`)).map((s) => s.id);
  oneOff({ kind: 'mesh', x: view.x, z: view.z, n: N3D, s: settings.size, structs }, (r) => {
    if (req !== terrainReq || settings.mode !== '3d') return;
    if (r.error) { $('hint3d').textContent = r.error; return; }
    lastMesh = r;
    $('hint3d').textContent = hint3d();
    view3d.show(r, pinsFor(r), { keepCamera });
  });
}
// Rebuild pins (e.g. after adding a waypoint) without regenerating terrain.
function refresh3D() {
  if (settings.mode === '3d' && view3d && lastMesh) view3d.show(lastMesh, pinsFor(lastMesh), { keepCamera: true });
}
for (const b of document.querySelectorAll('#sizes button'))
  b.onclick = () => { settings.size = +b.dataset.s; syncSizes(); saveHash(); enter3D(); };
function syncSizes() {
  for (const b of document.querySelectorAll('#sizes button')) {
    b.classList.toggle('on', +b.dataset.s === settings.size);
    b.setAttribute('aria-checked', +b.dataset.s === settings.size);
  }
}
$('coords-toggle').insertAdjacentHTML('afterbegin', svg('coords', 14));
$('coords-toggle').onclick = () => {
  const onNow = $('coords-toggle').classList.toggle('on');
  $('coords-toggle').setAttribute('aria-pressed', onNow);
  view3d?.setCoords(onNow);
};

// ---------- waypoints ----------
function addWaypoint(x, z, name) {
  if (waypoints.length >= 100) return;
  x = Math.round(x); z = Math.round(z);
  waypoints.push({ name: name || `Pin ${waypoints.length + 1}`, x, z, dim: settings.dim });
  renderWaypoints();
  saveHash();
  nearbySig = '';
  draw();
  refresh3D();
}
function renderWaypoints() {
  const ol = $('waypoints');
  ol.replaceChildren(...waypoints.map((w, i) => {
    if (w.dim !== settings.dim) return '';
    const li = document.createElement('li');
    li.innerHTML = `<span class="swatch" style="background:${WAYPOINT.color}">${svg('pin', 14)}</span>
      <input value="" aria-label="Waypoint name" maxlength="40">
      <small title="Go here">${w.x}, ${w.z}</small>
      <button class="icon-btn" aria-label="Remove waypoint">${svg('close', 14)}</button>`;
    const input = li.querySelector('input');
    input.value = w.name;
    input.onchange = () => { w.name = input.value.trim() || w.name; saveHash(); draw(); refresh3D(); };
    li.querySelector('small').onclick = () => flyTo(w.x, w.z);
    li.querySelector('button').onclick = () => { waypoints.splice(i, 1); renderWaypoints(); saveHash(); draw(); refresh3D(); };
    return li;
  }).filter(Boolean));
}
$('add-pin').innerHTML = svg('pin', 15);
$('add-pin').onclick = () => {
  const x = parseFloat($('goto-x').value), z = parseFloat($('goto-z').value);
  if (Number.isFinite(x) && Number.isFinite(z)) { addWaypoint(x, z); flyTo(x, z); }
  else $('goto-x').focus();
};
canvas.addEventListener('contextmenu', (e) => {
  e.preventDefault();
  const [x, z] = toWorld(e.offsetX, e.offsetY);
  addWaypoint(x, z);
});

// ---------- seed finder ----------
const finder = initFinder({
  structs: STRUCTS,
  biomes: () => (world?.overworld ?? []).map((id) => [id, world.names[id]]).sort((a, b) => a[1].localeCompare(b[1])),
  mc: () => settings.mc,
  parseSeed, randomSeed, pretty,
  open(seed, x, z, dim) {
    setSeedText(seed);
    if (dim !== settings.dim) { settings.dim = dim; syncSegs(); buildLayers(); }
    view.x = x; view.z = z;
    view.ppb = Math.max(view.ppb, 0.5);
    regenerate();
  },
});

$('goto').onsubmit = (e) => {
  e.preventDefault();
  const x = parseFloat($('goto-x').value), z = parseFloat($('goto-z').value);
  if (Number.isFinite(x) && Number.isFinite(z)) flyTo(x, z);
};
const centre = () => [canvas.clientWidth / 2, canvas.clientHeight / 2];
$('zoom-in').onclick = () => zoomAt(2, ...centre());
$('zoom-out').onclick = () => zoomAt(0.5, ...centre());
$('share').onclick = async () => {
  saveHash();
  try { await navigator.clipboard.writeText(location.href); $('share').textContent = 'Copied'; }
  catch { $('share').textContent = 'Copy failed'; }
  setTimeout(() => ($('share').textContent = 'Share'), 1200);
};
$('layers-toggle').onclick = () => {
  const c = $('layers-card').classList.toggle('collapsed');
  $('layers-toggle').setAttribute('aria-expanded', !c);
};
window.addEventListener('keydown', (e) => {
  if (e.target.matches('input, select')) return;
  if (e.key === '+' || e.key === '=') zoomAt(2, ...centre());
  if (e.key === '-') zoomAt(0.5, ...centre());
  const pan = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[e.key];
  if (pan && settings.mode === '3d') {
    e.preventDefault();
    const step = (N3D * settings.size) / 4;
    view.x += pan[0] * step;
    view.z += pan[1] * step;
    saveHash();
    enter3D({ keepCamera: true });
    return;
  }
  if (pan) {
    e.preventDefault();
    const step = (e.shiftKey ? 400 : 120) / view.ppb;
    view.x += pan[0] * step;
    view.z += pan[1] * step;
    changed();
  }
});

function resize() {
  const dpr = devicePixelRatio;
  canvas.width = Math.round(canvas.clientWidth * dpr);
  canvas.height = Math.round(canvas.clientHeight * dpr);
  changed();
}
new ResizeObserver(resize).observe(canvas);
// Re-render crisply after moving to a screen with a different pixel density.
(function watchDpr() {
  matchMedia(`(resolution: ${devicePixelRatio}dppx)`).addEventListener('change', () => { resize(); watchDpr(); }, { once: true });
})();

if (matchMedia('(max-width: 760px)').matches) {
  $('layers-card').classList.add('collapsed');
  $('layers-toggle').setAttribute('aria-expanded', 'false');
}
loadHash();
syncSegs();
buildLayers();
syncSizes();
renderWaypoints();
resize();
regenerate();

// Offline support and instant repeat loads (skipped in local development).
if ('serviceWorker' in navigator && !['localhost', '127.0.0.1'].includes(location.hostname))
  navigator.serviceWorker.register('sw.js').catch(() => {});
